/// <summary>
///     The <c>AVACustTableFrm_KCS_DirProductGroupDS_Extension</c> class is the extension for <c>CustTable</c>
/// </summary>
[ExtensionOf(FormDatasourceStr(CustTable, KCS_DirProductGroup))]
final class AVACustTableFrm_KCS_DirProductGroupDS_Extension
{
    [DataSource]
    class KCS_DirProductGroup
    {
        /// <summary>
        ///    AVA <c>editDirPartyIdRank1</c> method.
        /// </summary>
        /// <param name="_set">
        ///    <c>boolean</c> as type
        /// </param>
        /// <param name="_productGroup">
        ///    <c>KCS_DirProductGroup</c> as type
        /// </param>
        /// <param name="_name">
        ///    <c>str</c> as type
        /// </param>
        /// <returns>
        ///    <c>KCS_DirPartyName1</c> as return value
        /// </returns>
        edit KCS_DirPartyName1 editDirPartyIdRank1( boolean             _set,
                                                    KCS_DirProductGroup _productGroup,
                                                    str                 _name)
        {
            KCS_DirPartyName1   retVal;

            retVal = KCS_DirProductGroup.editPartyCompetitor(   _set,
                                                                frmDirPartyTable.RecId,
                                                                KCS_DirProductGrpAddressRanking::one,
                                                                _productGroup.KCS_DirProductGroupID,
                                                                CustTable.AccountNum);
            frmDirPartyRecId    = 0;
            frmDirPartyName     = '';

            return retVal;
        }

        /// <summary>
        ///    AVA <c>editDirPartyIdRank2</c> method.
        /// </summary>
