        ///    <c>boolean</c> as type
        /// </param>
        /// <param name="_productGroup">
        ///    <c>KCS_DirProductGroup</c> as type
        /// </param>
        /// <param name="_name">
        ///    <c>str</c> as type
        /// </param>
        /// <returns>
        ///    <c>KCS_DirPartyName2</c> as return value
        /// </returns>
        edit KCS_DirPartyName2 editDirPartyIdRank2( boolean             _set,
                                                    KCS_DirProductGroup _productGroup,
                                                    str                 _name)
        {
            KCS_DirPartyName2   retVal;

            retVal = KCS_DirProductGroup.editPartyCompetitor(   _set,
                                                                frmDirPartyTable.RecId,
                                                                KCS_DirProductGrpAddressRanking::two,
                                                                _productGroup.KCS_DirProductGroupID,
                                                                CustTable.AccountNum);
            frmDirPartyRecId    = 0;
            frmDirPartyName     = '';

            return retVal;
        }

        /// <summary>
