        /// </param>
        /// <returns>
        ///    <c>KCS_DirPartyName3</c> as return value
        /// </returns>
        edit KCS_DirPartyName3 editDirPartyIdRank3( boolean             _set,
                                                    KCS_DirProductGroup _productGroup,
                                                    str                 _name)
        {
            KCS_DirPartyName3   retVal;

            retVal =  KCS_DirProductGroup.editPartyCompetitor(  _set,
                                                                frmDirPartyTable.RecId,
                                                                KCS_DirProductGrpAddressRanking::three,
                                                                _productGroup.KCS_DirProductGroupID,
                                                                CustTable.AccountNum);
            frmDirPartyRecId    = 0;
